const productsData = [];

const categories = ["Books", "Electronics", "Notes", "Fashion", "Accessories"];

for (let i = 1; i <= 30; i++) {
  productsData.push({
    id: i,
    title: `Product ${i} Title`,
    price: Math.floor(Math.random() * 500) + 10,
    category: categories[i % categories.length],
    image: `https://source.unsplash.com/500x500/?${categories[i % categories.length]}`,
    description: `This is description for product ${i}. Useful for college students.`,
    postedDate: `${Math.floor(Math.random() * 7) + 1} days ago`,
    condition: ["New", "Like New", "Good"][i % 3],

    // Book fields
    pages: i % 2 === 0 ? 200 + i : undefined,
    author: i % 2 === 0 ? "Author Name" : undefined,

    // Electronics fields
    processor: i % 3 === 0 ? "Intel i5" : undefined,
    ram: i % 3 === 0 ? "8GB" : undefined,
    storage: i % 3 === 0 ? "512GB SSD" : undefined,
    battery: i % 3 === 0 ? "5 hrs" : undefined,

    // General
    brand: i % 4 === 0 ? "BrandX" : undefined,
    warranty: i % 4 === 0 ? "6 months" : undefined,

    // Seller Info (IMPORTANT)
    name: `User ${i}`,
    contact: `98${Math.floor(10000000 + Math.random() * 89999999)}`,
    email: `user${i}@college.edu`,
    location: `Hostel ${String.fromCharCode(65 + (i % 5))}, Room ${100 + i}`
  });
}

export default productsData;
